mapper.update:
UPDATE orders
SET total_price = #{totalPrice}, actual_price = #{actualPrice}, payment_method = #{paymentMethod}, 
    payment_time = #{paymentTime}, status = #{status}, shipping_address = #{shippingAddress}, 
    shipping_name = #{shippingName}, shipping_phone = #{shippingPhone}, 
    shipping_time = #{shippingTime}, finish_time = #{finishTime}, updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT * FROM orders 
WHERE status = #{status} 
AND created_at < #{timeoutTime}
